-- ===================================================
-- Initialisation de la base de données sur Oracle
-- ===================================================

-- 1) Création des tables
-- Suppression de la séquence si elle existe déjà
--DROP SEQUENCE seq_P17_Epreuves;

-- Création de la séquence et de la table P17_Epreuves
CREATE SEQUENCE seq_P17_Epreuves START WITH 1 INCREMENT BY 1;

CREATE TABLE P17_Epreuves (
                              EpreuveID INT PRIMARY KEY,
                              EpreuveDistance VARCHAR2(50) CHECK (TRIM(LOWER(EpreuveDistance)) IN ('50m', '100m', '200m', '400m', '800m', '1500m', '4 x 100m', '4 x 200m')),
                              EpreuveType VARCHAR2(100) CHECK (TRIM(LOWER(EpreuveType)) IN ('nage libre', 'papillon', 'dos', 'brasse', 'quatre nages')),
                              EpreuveCategorie CHAR(1) CHECK (TRIM(UPPER(EpreuveCategorie)) IN ('H', 'F', 'M')),
                              EpreuveTour VARCHAR2(50) CHECK (TRIM(LOWER(EpreuveTour)) IN (
                                                                                           'serie 1', 'serie 2', 'serie 3', 'serie 4', 'serie 5',
                                                                                           'serie 6', 'serie 7', 'serie 8', 'serie 9', 'serie 10',
                                                                                           'demi-finale 1', 'demi-finale 2', 'finale', 'demi-finale barrage'
                                  )),
                              EpreuveDate VARCHAR2(10), -- VARCHAR pour éviter des erreurs de type lors de l'alimentation
                              EpreuveHeure VARCHAR2(8) -- VARCHAR pour éviter des erreurs de type lors de l'alimentation
);

CREATE OR REPLACE TRIGGER trg_P17_Epreuves
    BEFORE INSERT ON P17_Epreuves
    FOR EACH ROW
BEGIN
    :NEW.EpreuveID := seq_P17_Epreuves.NEXTVAL;
END;
/

-- Suppression de la séquence si elle existe déjà
--DROP SEQUENCE seq_P17_Nageurs;

-- Création de la séquence et de la table P17_Nageurs
CREATE SEQUENCE seq_P17_Nageurs START WITH 1 INCREMENT BY 1;

CREATE TABLE P17_Nageurs (
                             NageurID INT PRIMARY KEY,
                             NageurNom VARCHAR2(50),
                             NageurPrenom VARCHAR2(50),
                             NageurSexe CHAR(1) CHECK (TRIM(UPPER(NageurSexe)) IN ('H', 'F')),
                             NageurPays CHAR(3),
                             NageurDateNaissance VARCHAR2(10) -- VARCHAR pour éviter des erreurs de type lors de l'alimentation
);

CREATE OR REPLACE TRIGGER trg_P17_Nageurs
    BEFORE INSERT ON P17_Nageurs
    FOR EACH ROW
BEGIN
    :NEW.NageurID := seq_P17_Nageurs.NEXTVAL;
END;
/

-- Suppression de la séquence si elle existe déjà
--DROP SEQUENCE seq_P17_RelaisEquipe;

-- Création de la séquence et de la table P17_RelaisEquipe
CREATE SEQUENCE seq_P17_RelaisEquipe START WITH 1 INCREMENT BY 1;

CREATE TABLE P17_RelaisEquipe (
                                  RelaisEquipeID INT PRIMARY KEY,
                                  RelaisEquipePays CHAR(3)
);

CREATE OR REPLACE TRIGGER trg_P17_RelaisEquipe
    BEFORE INSERT ON P17_RelaisEquipe
    FOR EACH ROW
BEGIN
    :NEW.RelaisEquipeID := seq_P17_RelaisEquipe.NEXTVAL;
END;
/

-- Table P17_ComposerEquipe
CREATE TABLE P17_ComposerEquipe (
                                    RelaisEquipeID INT,
                                    NageurID INT,
                                    PRIMARY KEY (RelaisEquipeID, NageurID),
                                    FOREIGN KEY (RelaisEquipeID) REFERENCES P17_RelaisEquipe(RelaisEquipeID),
                                    FOREIGN KEY (NageurID) REFERENCES P17_Nageurs(NageurID)
);

-- Table P17_ParticiperEquipe
CREATE TABLE P17_ParticiperEquipe (
                                      RelaisEquipeID INT,
                                      EpreuveID INT,
                                      Position INT,
                                      Temps VARCHAR2(10),
                                      Couloir INT,
                                      Medaille VARCHAR2(10) CHECK (TRIM(LOWER(Medaille)) IN ('or', 'argent', 'bronze', 'aucune')),
                                      PRIMARY KEY (RelaisEquipeID, EpreuveID),
                                      FOREIGN KEY (RelaisEquipeID) REFERENCES P17_RelaisEquipe(RelaisEquipeID),
                                      FOREIGN KEY (EpreuveID) REFERENCES P17_Epreuves(EpreuveID)
);

-- Table P17_ParticiperIndividuel
CREATE TABLE P17_ParticiperIndividuel (
                                          NageurID INT,
                                          EpreuveID INT,
                                          Position INT,
                                          Temps VARCHAR2(10),
                                          Couloir INT,
                                          Medaille VARCHAR2(10) CHECK (TRIM(LOWER(Medaille)) IN ('or', 'argent', 'bronze', 'aucune')),
                                          PRIMARY KEY (NageurID, EpreuveID),
                                          FOREIGN KEY (NageurID) REFERENCES P17_Nageurs(NageurID),
                                          FOREIGN KEY (EpreuveID) REFERENCES P17_Epreuves(EpreuveID)
);


-- Tables utilisées par les triggers
CREATE TABLE P17_Statistiques (
                                  StatID NUMBER PRIMARY KEY,
                                  NbTotalNageurs NUMBER
);

CREATE TABLE P17_HistoriqueModifications (
                                             HistoriqueID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
                                             OperationType VARCHAR2(10),
                                             NageurID NUMBER,
                                             EpreuveID NUMBER,
                                             DateModification TIMESTAMP,
                                             ValeursAnciennes CLOB,
                                             ValeursNouvelles CLOB
);

-- 2) Création des VUES
CREATE OR REPLACE VIEW P17_Vue_MedaillesNageur AS
SELECT
    N.NageurNom,
    N.NageurPrenom,
    N.NageurPays,
    SUM(CASE WHEN PI.Medaille = 'Or' THEN 1 ELSE 0 END) AS Nb_Or,
    SUM(CASE WHEN PI.Medaille = 'Argent' THEN 1 ELSE 0 END) AS Nb_Argent,
    SUM(CASE WHEN PI.Medaille = 'Bronze' THEN 1 ELSE 0 END) AS Nb_Bronze
FROM
    P17_Nageurs N
        JOIN P17_ParticiperIndividuel PI ON N.NageurID = PI.NageurID
GROUP BY
    N.NageurNom, N.NageurPrenom, N.NageurPays;

CREATE OR REPLACE VIEW P17_Vue_CalendrierEpreuves AS
SELECT
    E.EpreuveDate,
    E.EpreuveDistance,
    E.EpreuveType,
    E.EpreuveTour,
    PI.Position,
    N.NageurNom,
    N.NageurPrenom,
    PI.Temps
FROM
    P17_Epreuves E
        JOIN P17_ParticiperIndividuel PI ON E.EpreuveID = PI.EpreuveID
        JOIN P17_Nageurs N ON N.NageurID = PI.NageurID
ORDER BY
    E.EpreuveDate, E.EpreuveDistance, PI.Position;

CREATE OR REPLACE VIEW P17_Vue_EquipesGagnantes AS
SELECT
    E.EpreuveDate,
    E.EpreuveDistance,
    E.EpreuveType,
    E.EpreuveTour,
    PE.Medaille,
    RE.RelaisEquipePays
FROM
    P17_Epreuves E
        JOIN P17_ParticiperEquipe PE ON E.EpreuveID = PE.EpreuveID
        JOIN P17_RelaisEquipe RE ON RE.RelaisEquipeID = PE.RelaisEquipeID
WHERE
    PE.Medaille IN ('Or', 'Argent', 'Bronze');

-- 3) Création des FONCTIONS et PROCEDURES

CREATE OR REPLACE PROCEDURE P17_Proc_UpdateTemps (
    NagID IN NUMBER,
    IDEpreuve IN NUMBER,
    NouveauTemps IN VARCHAR2
)
AS
BEGIN
    UPDATE P17_ParticiperIndividuel
    SET Temps = NouveauTemps
    WHERE NageurID = NagID AND EpreuveID = IDEpreuve;
END;
/

CREATE OR REPLACE FUNCTION P17_Func_MedaillesOr (
    NagID IN NUMBER
) RETURN NUMBER IS
    total_or NUMBER;
BEGIN
    SELECT COUNT(*)
    INTO total_or
    FROM P17_ParticiperIndividuel
    WHERE NageurID = NagID AND Medaille = 'Or';
    RETURN total_or;
END;
/

CREATE OR REPLACE PROCEDURE P17_Proc_AfficheGagnantMedaille IS
    CURSOR cur IS
        SELECT DISTINCT N.NageurNom, N.NageurPrenom
        FROM P17_Nageurs N
                 JOIN P17_ParticiperIndividuel PI ON N.NageurID = PI.NageurID
        WHERE PI.Medaille IN ('Or', 'Argent', 'Bronze');
BEGIN
    FOR record IN cur LOOP
            DBMS_OUTPUT.PUT_LINE('Nageur: ' || record.NageurNom || ' ' || record.NageurPrenom);
        END LOOP;
END;
/

CREATE OR REPLACE PROCEDURE P17_Proc_LogModifications(
    operation_type IN VARCHAR2,
    old_values IN OUT CLOB,
    new_values IN OUT CLOB,
    nageur_id IN NUMBER,
    epreuve_id IN NUMBER
)
AS
BEGIN
        OperationType,
        NageurID,
        EpreuveID,
        DateModification,
        ValeursAnciennes,
        ValeursNouvelles
    )
    VALUES (
               operation_type,
               nageur_id,
               epreuve_id,
               SYSTIMESTAMP,
               old_values,
               new_values
           );
END;
/

-- 4) Création des TRIGGERS
CREATE OR REPLACE TRIGGER P17_Trigger_UpdateTotalNageurs
    AFTER INSERT OR DELETE ON P17_Nageurs
    FOR EACH ROW
BEGIN
    MERGE INTO P17_Statistiques S
    USING (SELECT COUNT(*) AS Total FROM P17_Nageurs) T
    ON (S.StatID = 1)
    WHEN MATCHED THEN
        UPDATE SET S.NbTotalNageurs = T.Total
    WHEN NOT MATCHED THEN
        INSERT (StatID, NbTotalNageurs) VALUES (1, T.Total);
END;
/

CREATE OR REPLACE TRIGGER P17_Trigger_LogModifications
    AFTER INSERT OR UPDATE OR DELETE ON P17_ParticiperIndividuel
    FOR EACH ROW
DECLARE
    old_values CLOB := NULL;
    new_values CLOB := NULL;
BEGIN
    -- Convertir les anciennes et nouvelles valeurs en JSON
    IF UPDATING OR DELETING THEN
        old_values := JSON_OBJECT(
                'NageurID' VALUE :OLD.NageurID,
                'EpreuveID' VALUE :OLD.EpreuveID,
                'Position' VALUE :OLD.Position,
                'Temps' VALUE :OLD.Temps,
                'Couloir' VALUE :OLD.Couloir,
                'Medaille' VALUE :OLD.Medaille
                      );
    END IF;

    IF INSERTING OR UPDATING THEN
        new_values := JSON_OBJECT(
                'NageurID' VALUE :NEW.NageurID,
                'EpreuveID' VALUE :NEW.EpreuveID,
                'Position' VALUE :NEW.Position,
                'Temps' VALUE :NEW.Temps,
                'Couloir' VALUE :NEW.Couloir,
                'Medaille' VALUE :NEW.Medaille
                      );
    END IF;

    -- Appel de la procédure pour enregistrer les modifications
    P17_Proc_LogModifications(
            operation_type => CASE
                                  WHEN INSERTING THEN 'INSERT'
                                  WHEN UPDATING THEN 'UPDATE'
                                  WHEN DELETING THEN 'DELETE'
                END,
            old_values => old_values,
            new_values => new_values,
            nageur_id => COALESCE(:OLD.NageurID, :NEW.NageurID),
            epreuve_id => COALESCE(:OLD.EpreuveID, :NEW.EpreuveID)
    );
END;
/


-- 5) Message de confirmation
BEGIN
    DBMS_OUTPUT.PUT_LINE('Base de données initialisée avec succès ! Toutes les tables, vues, procédures, fonctions et triggers ont été créés.');
END;
/
